(() => {
'use strict';
const A=window.RachnaAPI;if(!A)return;
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=A.esc,money=A.money;
const ui={page:'home',project:null,tab:'overview',query:'',inquiryStage:'new',month:0,serviceDraft:[]};
const STATUS={new:'New enquiries',quote_pending:'Quotation pending',quote_made:'Quotations made',quote_sent:'Quotation sent',interested:'Interested',not_interested:'Not interested',awaiting_advance:'Advance pending',booked:'Booked',cancelled:'Cancelled',booked_elsewhere:'Booked elsewhere',lost:'Lost',passed_on:'Passed on',booking_cancelled:'Booking cancelled',planning:'Planning',in_progress:'In progress',completed:'Completed',draft:'Draft',sent:'Sent',accepted:'Accepted',rejected:'Rejected',pending:'Pending',paid:'Paid',delivered:'Delivered'};
const NAV=[{section:'Overview',items:[['home','Home'],['events','Event Management']]},{section:'Clients',items:[['clients','All Clients'],['booked-clients','Booked Clients'],['freelancers','My Freelancers']]},{section:'Finance',items:[['finance','Finance Manager']]},{section:'Storage',items:[['files','File Management'],['drive','Event Drive']]},{section:'Production',items:[['photo-edit','Photo Edit Tracker'],['video-edit','Video Edit Tracker'],['deliverables','Album & Pen Drive']]},{section:'Workspace',items:[['settings','Settings']]}];
const PIPE=[['new','New enquiries'],['quote_pending','Quotation pending'],['quote_made','Quotations made'],['quote_sent','Quotation sent'],['interested','Interested'],['not_interested','Not interested'],['awaiting_advance','Advance pending'],['booked','Booked'],['cancelled','Cancelled'],['booked_elsewhere','Booked elsewhere'],['lost','Lost'],['passed_on','Passed on'],['booking_cancelled','Booking cancelled']];
const AAV_PACKAGES=[['Essential Package','1 photographer + 1 videographer · 300+ edited photos · full video · highlight · Drive + Pendrive'],['Signature Package','2 photographers + 2 videographers · 600+ edited photos · candid · album · full video + highlight'],['Legacy Package','3 photographers + 2 cinematographers · 1000+ photos · cinematic coverage · drone · premium album'],['2-Day Story','Multi-day coverage built around a 2-day event timeline'],['3-Day Story','Multi-day coverage built around a 3-day event timeline'],['Multi-day / Custom','Custom dates, functions, coverage team and deliverables']];
const AAV_ADDONS=['Candid coverage','Cinematic coverage','Drone','Premium Karizma album','Social media reels','Additional photographer','Additional videographer','Pre-wedding','Post-wedding','Additional album','Photo frame'];
const PHOTO_STAGES=['Received','Culling','Selection','Editing','QC','Export','Delivered'];
const VIDEO_STAGES=['Received','Rough Cut','Review','Fine Cut','Color','Audio','Delivered'];
const RACHNA=()=>A.state.services.filter(s=>String(s.brand).toLowerCase()==='rachna'&&s.active!==false);
const AAVARTAN=()=>A.state.services.filter(s=>String(s.brand).toLowerCase()==='aavartan'&&s.active!==false);
const toast=(m,error=false)=>{const n=$('#toast');if(!n)return;n.textContent=m;n.className='toast show'+(error?' error':'');clearTimeout(window.__rt);window.__rt=setTimeout(()=>n.className='toast',2800)};
const closeModal=()=>$('#backdrop')?.classList.remove('show');
const modal=(title,body,actions='')=>{const n=$('#modal');if(!n)return;n.innerHTML=`<div class="modal-head"><div><div class="eyebrow">RACHNA OS</div><h2>${esc(title)}</h2></div><button class="close-btn" data-action="close">×</button></div><div class="modal-body">${body}</div><div class="modal-foot"><button class="btn" data-action="close">Cancel</button>${actions}</div>`;$('#backdrop').classList.add('show')};
const field=(label,id,type='text',value='',extra='')=>`<label class="field"><span>${esc(label)}</span><input id="${id}" type="${type}" value="${esc(value??'')}" ${extra}></label>`;
const select=(label,id,opts,value='')=>`<label class="field"><span>${esc(label)}</span><select id="${id}">${opts.map(o=>{const v=Array.isArray(o)?o[0]:o,l=Array.isArray(o)?o[1]:o;return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`}).join('')}</select></label>`;
const textarea=(label,id,value='')=>`<label class="field full"><span>${esc(label)}</span><textarea id="${id}">${esc(value??'')}</textarea></label>`;
const status=v=>`<span class="status ${esc(v||'')}">${esc(STATUS[v]||v||'—')}</span>`;
const metric=(label,value,note,icon='')=>`<div class="metric"><div class="metric-top"><span>${icon||'◦'}</span><small>${esc(label)}</small></div><strong>${value}</strong><em>${esc(note)}</em></div>`;
const empty=(t,n='No records yet.')=>`<div class="empty"><div class="empty-icon">⌁</div><b>${esc(t)}</b><span>${esc(n)}</span></div>`;
const pageHead=(eyebrow,title,sub,actions='')=>`<div class="page-head"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(sub)}</p></div><div class="actions">${actions}</div></div>`;
const customerOf=id=>A.state.customers.find(c=>c.id===id);const projectOf=id=>A.state.projects.find(p=>p.id===id);const fnOf=id=>A.state.functions.find(f=>f.id===id);const projectFunctions=p=>A.state.functions.filter(f=>f.project_id===p.id);const projectServices=p=>A.state.projectServices.filter(s=>s.project_id===p.id);const booked=p=>p?.status==='booked';const dateLabel=f=>`${f?.event_date_bs||'Date TBC'}`;
function ico(k){return ({home:'⌂',events:'▦',clients:'♙','booked-clients':'✓',freelancers:'✣',finance:'₨',files:'□',drive:'◫','photo-edit':'▧','video-edit':'▣',deliverables:'◇',settings:'⚙'})[k]||'•'}
function renderShell(){
 $('#nav').innerHTML=NAV.map(g=>`<div class="nav-group"><div class="nav-label">${esc(g.section)}</div>${g.items.map(([k,l])=>`<button class="nav-item ${(!ui.project&&ui.page===k)?'active':''}" data-route="${k}"><span class="nav-ico">${ico(k)}</span><span>${esc(l)}</span></button>`).join('')}</div>`).join('');
 $('#crumb').textContent=ui.project?'Event Workspace':NAV.flatMap(g=>g.items).find(x=>x[0]===ui.page)?.[1]||'Home';
 const u=A.state.user;$('#userName').textContent=u?(A.state.profile?.full_name||u.email?.split('@')[0]||'Owner'):'Offline';$('#userRole').textContent=u?(A.state.profile?.role||'Owner'):'Sign in';
}
function render(){renderShell();$('#page').innerHTML=ui.project?projectPage():({home:homePage,events:eventsPage,clients:clientsPage,'booked-clients':bookedClientsPage,freelancers:freelancersPage,finance:financePage,files:filesPage,drive:drivePage,'photo-edit':()=>editTrackerPage('photo'),'video-edit':()=>editTrackerPage('video'),deliverables:deliverablesPage,settings:settingsPage}[ui.page]||homePage)()}
function homePage(){const s=A.state,open=s.inquiries.filter(i=>!['lost','booked','cancelled','booking_cancelled','booked_elsewhere'].includes(i.status)).length,b=s.projects.filter(booked).length,inTotal=s.payments.filter(p=>p.direction==='in').reduce((a,p)=>a+Number(p.amount||0),0),upcoming=s.functions.filter(f=>f.event_date).sort((a,b)=>a.event_date.localeCompare(b.event_date)).slice(0,6),due=s.reminders.filter(r=>r.status==='open').sort((a,b)=>(a.due_at||'').localeCompare(b.due_at||'')).slice(0,5);return pageHead('Rachna + Aavartan','Business Command Center','Everything from enquiry to event day in one connected workspace.',`<button class="btn soft" data-action="quick-action">⚡ Quick action</button><button class="btn primary" data-action="new-inquiry">＋ Create enquiry</button>`)+`<div class="metrics">${metric('Open enquiries',open,'Sales pipeline','✉')}${metric('Booked clients',b,'Manual booking status','✓')}${metric('Cash received',money(inTotal),'Customer receipts','₨')}${metric('Upcoming functions',upcoming.length,'On the calendar','◫')}</div><div class="dashboard-grid"><section class="panel"><div class="panel-title"><div><div class="eyebrow">ENQUIRIES & QUOTATION</div><h2>Sales pipeline</h2><p>Know what needs attention now.</p></div><button class="link" data-route="events">Open event management →</button></div><div class="pipeline-mini">${PIPE.slice(0,8).map(([k,l])=>`<button data-action="inquiry-stage" data-stage="${k}" class="${ui.inquiryStage===k?'sel':''}"><span>${esc(l)}</span><b>${s.inquiries.filter(i=>i.status===k).length}</b></button>`).join('')}</div><div class="mini-list">${s.inquiries.filter(i=>i.status===ui.inquiryStage).slice(0,4).map(i=>{const c=customerOf(i.customer_id);return `<div class="mini-row"><div><b>${esc(i.event_name)}</b><small>${esc(c?.name||'—')} · ${esc(i.event_date_bs||'Date TBC')}</small></div>${status(i.status)}<button class="btn tiny" data-action="convert-inquiry" data-id="${i.id}">Open</button></div>`}).join('')||empty('No enquiries in this stage')}</div></section><section class="panel"><div class="panel-title"><div><div class="eyebrow">UPCOMING EVENTS</div><h2>Calendar at a glance</h2><p>BS calendar</p></div><button class="link" data-route="events">View events →</button></div><div class="agenda-list">${upcoming.map(f=>{const p=projectOf(f.project_id);return `<div class="agenda"><div class="agenda-date"><b>${esc(f.event_date_bs||'—')}</b></div><div><b>${esc(f.name)}</b><span>${esc(p?.event_code||'')} · ${esc(f.venue||'Venue TBC')}</span></div><button class="btn tiny" data-action="open-project" data-id="${f.project_id}">Open</button></div>`}).join('')||empty('No upcoming functions')}</div></section></div><div class="dashboard-grid second"><section class="panel dark"><div class="panel-title"><div><div class="eyebrow light">CREW REQUIRED</div><h2>Event staffing</h2><p>See required vs assigned across upcoming functions.</p></div><button class="btn ghost" data-route="freelancers">Manage crew →</button></div><div class="crew-counters"><div><span>Assignments</span><strong>${s.projectTeam.length}</strong></div><div><span>Active crew</span><strong>${s.team.filter(t=>t.active!==false).length}</strong></div><div class="warning"><span>Upcoming functions</span><strong>${upcoming.length}</strong></div></div><div class="role-strip">${['Photographer','Videographer','Cinematographer','Editor','Assistant','Drone'].map(r=>`<span>${r} <b>${s.team.filter(t=>(t.role||'').toLowerCase().includes(r.toLowerCase().split(' ')[0])).length}</b></span>`).join('')}</div></section><section class="panel"><div class="panel-title"><div><div class="eyebrow">REMINDERS</div><h2>Attention today</h2><p>Payments, vendor follow-ups and delivery deadlines.</p></div><button class="link" data-action="new-reminder">＋ Reminder</button></div>${due.map(r=>`<div class="mini-row"><div><b>${esc(r.title)}</b><small>${r.due_at?new Date(r.due_at).toLocaleString():'No due time'}</small></div><span class="priority ${r.priority}">${esc(r.priority)}</span><button class="btn tiny" data-action="done-reminder" data-id="${r.id}">Done</button></div>`).join('')||empty('No open reminders')}</section></div>`}
function eventsPage(){const q=(ui.query||'').toLowerCase(),rows=A.state.projects.filter(p=>!q||[p.name,p.event_code,p.brand,customerOf(p.customer_id)?.name].some(v=>String(v||'').toLowerCase().includes(q)));return pageHead('Event Management','Events','Your spreadsheet-style master Event ID register.',`<input class="search" id="eventSearch" value="${esc(ui.query)}" placeholder="Search Event ID, client or event"><button class="btn primary" data-action="new-project">＋ New event</button>`)+`<div class="summary-bar"><span><b>${rows.length}</b> events</span><span><b>${A.state.projects.filter(booked).length}</b> booked</span><span><b>${money(A.state.projects.reduce((a,p)=>a+Number(p.quoted_total||0),0))}</b> quoted</span><span><b>${money(A.state.projects.reduce((a,p)=>a+Number(p.customer_advance||0),0))}</b> received</span></div><div class="panel table-panel"><table><thead><tr><th>Event ID</th><th>Client / Event</th><th>Functions</th><th>Status</th><th>Quoted</th><th>Paid</th><th>Balance</th><th>Profit*</th><th></th></tr></thead><tbody>${rows.map(p=>{const c=customerOf(p.customer_id),fs=projectFunctions(p),bal=Math.max(0,Number(p.quoted_total||0)-Number(p.customer_advance||0)),profit=Number(p.quoted_total||0)-Number(p.internal_cost||0);return `<tr><td><b class="event-code">${esc(p.event_code||'Generating…')}</b><small>${esc(p.brand||'Rachna')}</small></td><td><b>${esc(p.name)}</b><small>${esc(c?.name||'No client')}</small></td><td><b>${fs.length}</b><small>${esc(fs.map(f=>f.name).slice(0,2).join(' · '))}</small></td><td>${status(p.status)}</td><td>${money(p.quoted_total)}</td><td>${money(p.customer_advance)}</td><td>${money(bal)}</td><td><b>${money(profit)}</b></td><td><button class="btn tiny" data-action="open-project" data-id="${p.id}">Open</button></td></tr>`}).join('')||`<tr><td colspan="9">${empty('No events','Create an event and its Event ID will connect every department.')}</td></tr>`}</tbody></table></div><div class="footnote">* Current profit is based on quoted total minus recorded internal cost and updates as operations costs are recorded.</div>`}
function projectPage(){const p=projectOf(ui.project);if(!p){ui.project=null;return homePage()}const c=customerOf(p.customer_id),fs=projectFunctions(p),sv=projectServices(p),qs=A.state.quotations.filter(q=>q.project_id===p.id),vp=A.state.vendorBookings.filter(v=>v.project_id===p.id),pt=A.state.projectTeam.filter(t=>t.project_id===p.id),pay=A.state.payments.filter(x=>x.project_id===p.id),jobs=A.state.productionJobs.filter(j=>j.project_id===p.id),files=A.state.eventFiles.filter(f=>f.project_id===p.id),rem=A.state.reminders.filter(r=>r.project_id===p.id),tabs=[['overview','Overview'],['functions','Functions'],['services','Services'],['quotation','Quotation'],['vendors','Vendors'],['crew','Crew'],['money','Money'],['production','Production'],['files','Files']],balance=Math.max(0,Number(p.quoted_total||0)-Number(p.customer_advance||0));return `<div class="event-head"><button class="back-btn" data-action="back-events">←</button><div><div class="eyebrow">EVENT ID</div><h1>${esc(p.event_code||'Event')}</h1><p>${esc(p.name)} · ${esc(c?.name||'No client')} · ${esc(c?.phone||'')}</p></div><div class="event-actions"><button class="btn" data-action="new-reminder" data-project="${p.id}">Reminder</button><button class="btn" data-action="new-payment" data-project="${p.id}">Payment</button><button class="btn primary" data-action="new-quote" data-project="${p.id}">＋ Quotation</button></div></div><div class="event-summary"><div><small>Customer</small><b>${esc(c?.name||'—')}</b><span>${esc(c?.phone||'')}</span></div><div><small>Functions</small><b>${fs.length}</b><span>${esc(fs.map(f=>f.name).slice(0,2).join(' · ')||'Not added')}</span></div><div><small>Quoted</small><b>${money(p.quoted_total)}</b><span>Advance ${money(p.customer_advance)}</span></div><div><small>Balance</small><b>${money(balance)}</b><span>${booked(p)?'Booking confirmed':'Manual booking status'}</span></div><div><small>Status</small>${status(p.status)}<span>${esc(p.brand||'Rachna + Aavartan')}</span></div></div><div class="tabs">${tabs.map(([k,l])=>`<button class="${ui.tab===k?'active':''}" data-project-tab="${k}">${l}</button>`).join('')}</div>${ui.tab==='overview'?overviewTab(p,fs,sv,vp,pt,jobs,rem):ui.tab==='functions'?functionsTab(p,fs):ui.tab==='services'?servicesTab(p,sv,fs):ui.tab==='quotation'?quotationTab(p,qs,sv):ui.tab==='vendors'?vendorsTab(p,vp,fs):ui.tab==='crew'?crewTab(p,pt,fs):ui.tab==='money'?projectMoneyTab(p,pay):ui.tab==='production'?productionTab(p,jobs,fs):filesTab(p,files)}`}
function overviewTab(p,fs,sv,vp,pt,jobs,rem){const hasAav=sv.some(s=>String(s.name).toLowerCase().includes('aavartan photo + video'));return `<div class="grid3"><section class="panel"><div class="eyebrow">EVENT PLAN</div><h2>Functions</h2>${fs.map(f=>`<div class="list-card"><div><b>${esc(f.name)}</b><small>${esc(dateLabel(f))}</small><span>${esc(f.venue||'Venue TBC')} · ${f.guest_count||0} guests</span></div></div>`).join('')||empty('No functions','Add Mehendi, Engagement, Wedding, Reception or any custom function.')}</section><section class="panel"><div class="eyebrow">SERVICE SCOPE</div><h2>${sv.length} services</h2>${sv.map(s=>`<div class="list-card"><div><b>${esc(s.name)}</b><small>${money(s.customer_price)} customer · ${money(s.internal_cost)} internal</small></div></div>`).join('')||empty('No services','Select Rachna services and/or Aavartan independently.')}</section><section class="panel"><div class="eyebrow">OPERATIONS</div><h2>Connected work</h2>${[['Vendor jobs',vp.length,'vendors'],['Crew assignments',pt.length,'crew'],['Production jobs',jobs.length,'production'],['Reminders',rem.length,'overview']].map(x=>`<button class="jump-card" data-project-tab="${x[2]}"><b>${x[1]}</b><span>${x[0]}</span><i>→</i></button>`).join('')}</section></div><section class="panel callout"><div><div class="eyebrow">AAVARTAN CORE</div><h2>${hasAav?'Photo + Video is connected to this event.':'Not added to this event.'}</h2><p>Rachna services and Aavartan Photo + Video are independent. Add only what this client booked.</p></div><button class="btn primary" data-project-tab="services">${hasAav?'Manage scope':'Add services'}</button></section>`}
function functionsTab(p,fs){return `<section class="panel"><div class="section-head"><div><div class="eyebrow">EVENT TIMELINE</div><h2>Functions</h2><p>Each function gets its own date, venue, staffing and service scope.</p></div><button class="btn primary" data-action="new-function" data-project="${p.id}">＋ Add function</button></div><div class="function-grid">${fs.map(f=>`<div class="function-card"><div class="date-tile"><b>${esc(f.event_date_bs||'—')}</b></div><div><h3>${esc(f.name)}</h3><p>${esc(f.venue||'Venue TBC')}</p><small>${esc(f.guest_count||0)} guests${f.start_time?' · '+f.start_time:''}</small></div><button class="btn tiny" data-action="edit-function" data-id="${f.id}">Edit</button></div>`).join('')||empty('No functions yet')}</div></section>`}
function servicesTab(p,sv){const rach=RACHNA(),aav=AAVARTAN(),aavSelected=sv.find(s=>String(s.name).toLowerCase().includes('aavartan photo + video')),coreId=aavSelected?.service_id||AAVARTAN().find(x=>x.name==='Aavartan Photo + Video')?.id||'';return `<section class="panel"><div class="section-head"><div><div class="eyebrow">SCOPE BUILDER</div><h2>What did this client book?</h2><p>Nothing is selected automatically. Rachna and Aavartan are independent.</p></div><button class="btn primary" data-action="save-services" data-project="${p.id}">Save scope</button></div><div class="service-builder"><div><div class="service-brand rachna">RACHNA · EVENT MANAGEMENT</div><div class="choice-grid">${rach.map(s=>`<label class="choice"><input type="checkbox" data-svc data-brand="Rachna" data-service-id="${s.id}" data-name="${esc(s.name)}" ${sv.some(v=>v.service_id===s.id||v.name===s.name)?'checked':''}><span><b>${esc(s.name)}</b><small>${esc(s.category||'Service')}</small></span></label>`).join('')}</div></div><div><div class="service-brand aavartan">AAVARTAN · PHOTOGRAPHY + VIDEO</div><label class="choice hero-choice"><input type="checkbox" id="aavartanCore" data-service-id="${coreId}" ${aavSelected?'checked':''}><span><b>Photo + Video</b><small>One combined core service. Package is chosen only when enabled.</small></span></label><div id="aavartanOptions" class="${aavSelected?'':'hidden'}"><div class="package-grid">${AAV_PACKAGES.map(([n,d])=>`<label class="package"><input type="radio" name="aavPkg" value="${esc(n)}" ${aavSelected&&String(aavSelected.name).toLowerCase().includes(n.toLowerCase())?'checked':''}><span><b>${esc(n)}</b><small>${esc(d)}</small></span></label>`).join('')}</div><div class="choice-grid addon-grid">${AAV_ADDONS.map(n=>`<label class="choice"><input type="checkbox" data-addon data-name="${esc(n)}" ${sv.some(v=>v.name===n||v.name.startsWith(n+' —'))?'checked':''}><span><b>${esc(n)}</b></span></label>`).join('')}</div></div></div><div class="scope-note">Client price and internal cost are stored on the Event ID. Enter the exact amount agreed with the client.</div></div></section>`}
function quotationTab(p,qs){const q=qs[0],items=q?A.state.quotationItems.filter(i=>i.quotation_id===q.id):[];return `<section class="panel"><div class="section-head"><div><div class="eyebrow">QUOTATION</div><h2>${q?'Quotation v'+q.version:'No quotation yet'}</h2><p>${q?`Status: ${esc(STATUS[q.status]||q.status)} · Customer total ${money(q.customer_total)}`:'Create a quotation from this Event ID scope.'}</p></div><div class="actions">${q?`<button class="btn" data-action="quote-status" data-id="${q.id}" data-status="sent" data-project="${p.id}">Mark sent</button><button class="btn" data-action="quote-status" data-id="${q.id}" data-status="accepted" data-project="${p.id}">Accepted</button>`:`<button class="btn primary" data-action="new-quote" data-project="${p.id}">＋ Create quotation</button>`}</div></div>${q?`<div class="quote-meta"><div><span>Customer total</span><b>${money(q.customer_total)}</b></div><div><span>Internal total</span><b>${money(q.internal_total)}</b></div><div><span>Margin</span><b>${money(Number(q.customer_total||0)-Number(q.internal_total||0))}</b></div><div><span>Version</span><b>v${q.version}</b></div></div><div class="quote-items">${items.map(i=>`<div class="quote-line"><div><b>${esc(i.description||'Item')}</b><small>${i.quantity||1} × ${money(i.customer_price)}</small></div><b>${money(Number(i.quantity||1)*Number(i.customer_price||0))}</b></div>`).join('')||empty('Quotation has no items','Use Add item below.')}</div><button class="btn soft" data-action="new-quote-item" data-quote="${q.id}" data-project="${p.id}">＋ Add quotation item</button>`:empty('No quotation yet')}</section>`}
function vendorsTab(p,vp){return `<section class="panel"><div class="section-head"><div><div class="eyebrow">VENDOR JOBS</div><h2>Assigned vendors</h2><p>Requirement, customer price, vendor cost, advance and payable.</p></div><button class="btn primary" data-action="new-vendor-job" data-project="${p.id}">＋ Vendor job</button></div><div class="vendor-board">${vp.map(v=>{const vd=A.state.vendors.find(x=>x.id===v.vendor_id),bal=Math.max(0,Number(v.quoted_cost||0)-Number(v.advance_paid||0)-Number(v.final_paid||0));return `<div class="vendor-card"><div><b>${esc(vd?.name||'Vendor')}</b><span>${esc(v.category||vd?.service_category||'')}</span></div><div><small>Requirement</small><b>${esc(v.requirement||'—')}</b></div><div><small>Customer</small><b>${money(v.client_price)}</b></div><div><small>Vendor cost</small><b>${money(v.quoted_cost)}</b></div><div><small>Payable</small><b>${money(bal)}</b></div>${status(v.status||'pending')}</div>`}).join('')||empty('No vendor jobs')}</div></section>`}
function crewTab(p,pt){return `<section class="panel"><div class="section-head"><div><div class="eyebrow">CREW</div><h2>Team assignments</h2><p>Assign people to the Event ID or a specific function.</p></div><button class="btn primary" data-action="assign-crew" data-project="${p.id}">＋ Assign crew</button></div><div class="crew-table"><table><thead><tr><th>Person</th><th>Role</th><th>Function</th><th>Rate</th></tr></thead><tbody>${pt.map(x=>{const t=A.state.team.find(v=>v.id===x.team_member_id),f=fnOf(x.function_id);return `<tr><td><b>${esc(t?.name||'—')}</b><small>${esc(t?.phone||'')}</small></td><td>${esc(t?.role||x.responsibility||'—')}</td><td>${esc(f?.name||'All functions')}</td><td>${money(x.rate)}</td></tr>`}).join('')||`<tr><td colspan="4">${empty('No crew assigned')}</td></tr>`}</tbody></table></div></section>`}
function projectMoneyTab(p,pay){const inT=pay.filter(x=>x.direction==='in').reduce((a,x)=>a+Number(x.amount||0),0),outT=pay.filter(x=>x.direction==='out').reduce((a,x)=>a+Number(x.amount||0),0),balance=Math.max(0,Number(p.quoted_total||0)-inT);return `<div class="metrics">${metric('Quoted',money(p.quoted_total),'Event value','₨')}${metric('Received',money(inT),'Customer receipts','↓')}${metric('Paid out',money(outT),'Outgoing payments','↑')}${metric('Balance',money(balance),'Still receivable','•')}</div><section class="panel"><div class="section-head"><div><div class="eyebrow">MONEY</div><h2>Event transactions</h2><p>Booking status is manual.</p></div><button class="btn primary" data-action="new-payment" data-project="${p.id}">＋ Record payment</button></div><div class="transaction-list">${pay.map(x=>`<div class="transaction"><div><b>${x.direction==='in'?'Customer receipt':'Outgoing payment'}</b><small>${esc(x.payment_date||'')} · ${esc(x.method||'')}</small></div><span class="${x.direction}">${x.direction==='in'?'+':'−'} ${money(x.amount)}</span></div>`).join('')||empty('No transactions')}</div></section>`}
function productionTab(p,jobs){const photo=jobs.filter(j=>(j.tracker_type||j.job_type)==='photo'),video=jobs.filter(j=>(j.tracker_type||j.job_type)==='video');return `<div class="tracker-grid"><section class="panel"><div class="section-head"><div><div class="eyebrow">PHOTO EDIT TRACKER</div><h2>${photo.length} jobs</h2></div><button class="btn primary" data-action="new-job" data-type="photo" data-project="${p.id}">＋ Add photo job</button></div><div class="stage-flow">${PHOTO_STAGES.map(s=>stageCount(photo,s)).join('')}</div>${photo.map(jobRow).join('')||empty('No photo jobs')}</section><section class="panel"><div class="section-head"><div><div class="eyebrow">VIDEO EDIT TRACKER</div><h2>${video.length} jobs</h2></div><button class="btn primary" data-action="new-job" data-type="video" data-project="${p.id}">＋ Add video job</button></div><div class="stage-flow">${VIDEO_STAGES.map(s=>stageCount(video,s)).join('')}</div>${video.map(jobRow).join('')||empty('No video jobs')}</section></div>`}
function stageCount(jobs,stage){return `<div><small>${esc(stage)}</small><b>${jobs.filter(j=>String(j.stage).toLowerCase()===String(stage).toLowerCase()).length}</b></div>`}
function jobRow(j){const stages=(j.tracker_type||j.job_type)==='photo'?PHOTO_STAGES:VIDEO_STAGES;return `<div class="job-row"><div><b>${esc(j.title||'Production job')}</b><small>${esc(j.due_date||'No due date')}</small></div><select class="stage-select" data-job-stage="${j.id}">${stages.map(s=>`<option value="${esc(s)}" ${String(j.stage).toLowerCase()===String(s).toLowerCase()?'selected':''}>${esc(s)}</option>`).join('')}</select><span class="stage-pill">${esc(j.status||'pending')}</span></div>`}
function filesTab(p,files){return `<section class="panel"><div class="section-head"><div><div class="eyebrow">EVENT FILES</div><h2>File management</h2><p>Keep gallery, Drive, reference and delivery links attached to ${esc(p.event_code||'this Event ID')}.</p></div><button class="btn primary" data-action="new-file" data-project="${p.id}">＋ Add file / link</button></div><div class="file-grid">${files.map(f=>`<div class="file-card"><div class="file-icon">${esc((f.kind||'link').slice(0,1).toUpperCase())}</div><div><b>${esc(f.name)}</b><small>${esc(f.kind||'link')} · ${esc(f.notes||'')}</small>${f.url?`<a href="${esc(f.url)}" target="_blank" rel="noreferrer">Open link →</a>`:''}</div><button class="btn tiny danger" data-action="delete-file" data-id="${f.id}">Delete</button></div>`).join('')||empty('No files attached')}</div></section>`}
function clientsPage(){const q=(ui.query||'').toLowerCase();return pageHead('Clients','All Clients','Every client connected to their Event IDs.',`<input class="search" id="clientSearch" value="${esc(ui.query)}" placeholder="Search client / phone"><button class="btn primary" data-action="new-client">＋ New client</button>`)+`<div class="panel table-panel"><table><thead><tr><th>Client</th><th>Phone</th><th>Events</th><th>Booked</th><th>Latest event</th></tr></thead><tbody>${A.state.customers.filter(c=>!q||[c.name,c.phone,c.email].some(v=>String(v||'').toLowerCase().includes(q))).map(c=>{const ps=A.state.projects.filter(p=>p.customer_id===c.id);return `<tr><td><b>${esc(c.name)}</b><small>${esc(c.email||'')}</small></td><td>${esc(c.phone||'—')}</td><td>${ps.length}</td><td>${ps.filter(booked).length}</td><td>${esc(ps[0]?.event_code||'—')} ${ps[0]?`<button class="link" data-action="open-project" data-id="${ps[0].id}">Open</button>`:''}</td></tr>`}).join('')||`<tr><td colspan="5">${empty('No clients')}</td></tr>`}</tbody></table></div>`}
function bookedClientsPage(){const ps=A.state.projects.filter(booked);return pageHead('Clients','Booked Clients','Confirmed Event IDs after the 30% customer advance gate.')+`<div class="card-grid">${ps.map(p=>{const c=customerOf(p.customer_id),fs=projectFunctions(p);return `<button class="event-card" data-action="open-project" data-id="${p.id}"><div class="event-code">${esc(p.event_code||'')}</div><h3>${esc(p.name)}</h3><p>${esc(c?.name||'—')} · ${esc(c?.phone||'')}</p><span>${esc(fs.map(f=>dateLabel(f)).slice(0,2).join(' · ')||'No functions')}</span><b>${money(p.quoted_total)}</b></button>`}).join('')||empty('No booked events')}</div>`}
function freelancersPage(){return pageHead('Workspace','My Freelancers','Crew directory and assignment readiness.','<button class="btn primary" data-action="new-team">＋ Add freelancer</button>')+`<div class="crew-grid">${A.state.team.map(t=>{const assigned=A.state.projectTeam.filter(x=>x.team_member_id===t.id).length;return `<div class="crew-card"><div class="avatar large">${esc((t.name||'T').slice(0,1).toUpperCase())}</div><div><b>${esc(t.name)}</b><span>${esc(t.role||'Crew')}</span><small>${esc(t.phone||'')}</small></div><strong>${assigned}</strong><em>assignments</em></div>`}).join('')||empty('No freelancers added')}</div>`}
function financePage(){const inT=A.state.payments.filter(x=>x.direction==='in').reduce((a,x)=>a+Number(x.amount||0),0),outT=A.state.payments.filter(x=>x.direction==='out').reduce((a,x)=>a+Number(x.amount||0),0),quoted=A.state.projects.reduce((a,p)=>a+Number(p.quoted_total||0),0),recv=Math.max(0,quoted-inT);return pageHead('Finance','Finance Manager','Company-wide cash, receivables, payables and event profitability.','<button class="btn primary" data-action="new-payment">＋ Record payment</button>')+`<div class="metrics">${metric('Quoted value',money(quoted),'Across all Event IDs','₨')}${metric('Cash in',money(inT),'Customer receipts','↓')}${metric('Cash out',money(outT),'Outgoing payments','↑')}${metric('Receivable',money(recv),'Outstanding','•')}</div><div class="dashboard-grid"><section class="panel"><div class="panel-title"><div><div class="eyebrow">EVENT PROFITABILITY</div><h2>Event financial board</h2><p>Quoted value minus recorded internal cost.</p></div></div><div class="finance-list">${A.state.projects.map(p=>`<div class="finance-row"><div><b>${esc(p.event_code||'')}</b><small>${esc(p.name)}</small></div><span>${money(p.quoted_total)}</span><span>${money(p.internal_cost)}</span><strong>${money(Number(p.quoted_total||0)-Number(p.internal_cost||0))}</strong></div>`).join('')||empty('No events')}</div></section><section class="panel"><div class="panel-title"><div><div class="eyebrow">RECENT TRANSACTIONS</div><h2>Cash movement</h2></div></div><div class="transaction-list">${A.state.payments.slice(0,8).map(x=>`<div class="transaction"><div><b>${x.direction==='in'?'Receipt':'Payment'}</b><small>${esc(x.payment_date||'')} · ${esc(projectOf(x.project_id)?.event_code||'Company')}</small></div><span class="${x.direction}">${x.direction==='in'?'+':'−'} ${money(x.amount)}</span></div>`).join('')||empty('No transactions')}</div></section></div>`}
function filesPage(){const q=(ui.query||'').toLowerCase();return pageHead('Storage','File Management','Find every event file by Event ID.',`<input class="search" id="fileSearch" value="${esc(ui.query)}" placeholder="Search Event ID / file">`)+`<div class="card-grid">${A.state.eventFiles.filter(f=>{const p=projectOf(f.project_id);return !q||[f.name,p?.event_code,p?.name].some(v=>String(v||'').toLowerCase().includes(q))}).map(f=>{const p=projectOf(f.project_id);return `<div class="file-card"><div class="file-icon">F</div><div><b>${esc(f.name)}</b><small>${esc(p?.event_code||'')} · ${esc(p?.name||'')}</small>${f.url?`<a href="${esc(f.url)}" target="_blank" rel="noreferrer">Open →</a>`:''}</div></div>`}).join('')||empty('No event files')}</div>`}
function drivePage(){return pageHead('Storage','Event Drive','A single place to keep external Drive / gallery links connected to an Event ID.')+`<section class="panel callout"><div><div class="eyebrow">CONNECTED STORAGE</div><h2>Event-linked, not scattered.</h2><p>Attach Google Drive, gallery, YouTube and client delivery links to the event workspace.</p></div><button class="btn primary" data-route="files">Open file management</button></section>`}
function editTrackerPage(type){const stages=type==='photo'?PHOTO_STAGES:VIDEO_STAGES,jobs=A.state.productionJobs.filter(j=>(j.tracker_type||j.job_type)===type);return pageHead('Production',type==='photo'?'Photo Edit Tracker':'Video Edit Tracker','Seven-stage production pipeline connected to Event IDs.',`<button class="btn primary" data-action="global-new-job" data-type="${type}">＋ New ${type} job</button>`)+`<div class="stage-overview">${stages.map(s=>stageCount(jobs,s)).join('')}</div><section class="panel"><div class="tracker-list">${jobs.map(j=>{const p=projectOf(j.project_id);return `<div class="tracker-row"><div><b>${esc(p?.event_code||'')}</b><small>${esc(j.title||'')}</small></div><span>${esc(j.stage)}</span><span>${esc(j.due_date||'No due date')}</span><button class="btn tiny" data-action="open-project" data-id="${j.project_id}">Event</button></div>`}).join('')||empty('No production jobs')}</div></section>`}
function deliverablesPage(){return pageHead('Production','Album & Pen Drive','Delivery queue for finished Aavartan work.','<button class="btn primary" data-action="new-deliverable">＋ Add deliverable</button>')+`<section class="panel"><div class="delivery-list">${A.state.deliverables.map(d=>{const p=projectOf(d.project_id);return `<div class="delivery-row"><div><b>${esc(p?.event_code||'')}</b><small>${esc(d.deliverable)}</small></div><span>${esc(d.due_date||'No due date')}</span>${status(d.status)}<button class="btn tiny" data-action="complete-deliverable" data-id="${d.id}" data-project="${d.project_id}">Mark delivered</button></div>`}).join('')||empty('No deliverables')}</div></section>`}
function settingsPage(){return pageHead('Workspace','Settings','Company rules, services and account controls.')+`<div class="settings-grid"><section class="panel"><div class="eyebrow">BOOKING RULES</div><h2>Your business logic</h2>${['Customer pays 30% advance before an event is considered booked.','15% of the customer advance is reserved for the vendor booking.','Rachna and Aavartan services are independent on the same Event ID.','BS is the primary event date with AD stored alongside it.','Event ID connects sales, operations, money and production.'].map((x,i)=>`<div class="rule"><b>0${i+1}</b><span>${esc(x)}</span></div>`).join('')}</section><section class="panel"><div class="eyebrow">SERVICE CATALOG</div><h2>Rachna</h2>${RACHNA().map(s=>`<div class="catalog-row"><span>${esc(s.name)}</span><b>${money(s.base_price)}</b></div>`).join('')}</section><section class="panel"><div class="eyebrow">SERVICE CATALOG</div><h2>Aavartan</h2>${AAVARTAN().map(s=>`<div class="catalog-row"><span>${esc(s.name)}</span><b>${money(s.base_price)}</b></div>`).join('')}</section><section class="panel"><div class="eyebrow">ACCOUNT</div><h2>${esc(A.state.profile?.full_name||'Owner')}</h2><p>${esc(A.state.user?.email||'')}</p><button class="btn" data-action="signout">Sign out</button></section></div>`}
function newInquiryModal(){modal('Create enquiry',`<div class="form-grid">${field('Customer name','inqCustomer')} ${field('Phone / WhatsApp','inqPhone','text','','inputmode="tel"')} ${field('Event / wedding name','inqEvent')} ${field('Source','inqSource','text','Instagram')} ${field('BS event date','inqDate','text','','placeholder="2083-08-25"')} ${field('Venue','inqVenue')} ${field('Guests','inqGuests','number','')} ${field('Budget','inqBudget','number','')} ${textarea('Notes','inqNotes')}</div>`,`<button class="btn primary" data-action="save-inquiry">Create enquiry</button>`)}
function newProjectModal(){modal('Create new Event',`<div class="rule-note">Create the master Event ID first. You can add multiple functions and either Rachna or Aavartan services afterward.</div><div class="form-grid">${field('Customer name','pCustomer')} ${field('Phone / WhatsApp','pPhone','text','','inputmode="tel"')} ${field('Event / wedding name','pName')} ${field('BS date range','pDate','text','','placeholder="2083-08-25 → 2083-08-27"')} ${field('First function','pFunction','text','Wedding')} ${field('Venue','pVenue')} ${field('Guests','pGuests','number','')} ${select('Brand scope','pBrand',[['Rachna','Rachna'],['Aavartan','Aavartan'],['Rachna + Aavartan','Rachna + Aavartan']])}</div>`,`<button class="btn primary" data-action="save-project">Create Event ID</button>`)}
function newFunctionModal(projectId){modal('Add event function',`<div class="form-grid">${field('Function name','fnName')} ${field('BS date','fnBS','text','','placeholder="2083-08-25"')} ${field('AD date','fnAD','date')} ${field('Start time','fnTime','time')} ${field('Venue','fnVenue')} ${field('Guests','fnGuests','number','')} ${textarea('Notes','fnNotes')}</div>`,`<button class="btn primary" data-action="save-function" data-project="${projectId}">Add function</button>`)}
function newClientModal(){modal('Add client',`<div class="form-grid">${field('Name','cName')} ${field('Phone','cPhone')} ${field('WhatsApp','cWhatsapp')} ${field('Email','cEmail')} ${textarea('Notes','cNotes')}</div>`,`<button class="btn primary" data-action="save-client">Create client</button>`)}
function newTeamModal(){modal('Add freelancer',`<div class="form-grid">${field('Name','tName')} ${field('Role','tRole','text','Photographer')} ${field('Phone','tPhone')} ${field('Email','tEmail')}</div>`,`<button class="btn primary" data-action="save-team">Add freelancer</button>`)}
function newPaymentModal(projectId=''){const projects=A.state.projects.map(p=>[p.id,`${p.event_code||''} · ${p.name}`]);modal('Record payment',`<div class="form-grid">${select('Event ID','payProject',projectId?projects:[['','Company / unassigned'],...projects],projectId)} ${select('Type','payType',[['advance','Customer advance'],['receipt','Other customer receipt'],['vendor','Vendor / outgoing payment'],['expense','Company expense']])} ${field('Amount','payAmount','number','')} ${field('Date','payDate','date',new Date().toISOString().slice(0,10))} ${select('Method','payMethod',['Cash','Bank transfer','eSewa','Khalti','Card','Other'])} ${field('Reference','payRef')} ${textarea('Notes','payNotes')}</div><div class="rule-note">For a customer advance, the 30% booking rule is enforced by the system.</div>`,`<button class="btn primary" data-action="save-payment">Record</button>`)}
function newReminderModal(projectId=''){modal('Create reminder',`<div class="form-grid">${field('Title','rTitle')} ${select('Priority','rPriority',['low','normal','high','urgent'],'normal')} ${field('Due','rDue','datetime-local')} ${select('Type','rType',['general','customer_followup','quotation','advance','vendor','crew','production','delivery'])} ${projectId?`<input id="rProject" type="hidden" value="${projectId}">`:select('Event ID','rProject',[['','Company'],...A.state.projects.map(p=>[p.id,`${p.event_code||''} · ${p.name}`])])} ${textarea('Notes','rNotes')}</div>`,`<button class="btn primary" data-action="save-reminder">Save reminder</button>`)}
function newVendorJobModal(projectId){modal('Add vendor job',`<div class="form-grid">${select('Vendor','vjVendor',A.state.vendors.map(v=>[v.id,v.name]))} ${select('Function','vjFunction',[['','All / project level'],...projectFunctions(projectOf(projectId)||{}).map(f=>[f.id,f.name])])} ${field('Category','vjCategory')} ${field('Requirement','vjRequirement')} ${field('Quantity','vjQuantity','number','1')} ${field('Customer price','vjClient','number','0')} ${field('Vendor cost','vjCost','number','0')} ${select('Status','vjStatus',['pending','reserved','paid','completed'])} ${textarea('Notes','vjNotes')}</div>`,`<button class="btn primary" data-action="save-vendor-job" data-project="${projectId}">Add vendor job</button>`)}
function assignCrewModal(projectId){modal('Assign crew',`<div class="form-grid">${select('Team member','crewPerson',A.state.team.filter(t=>t.active!==false).map(t=>[t.id,`${t.name} · ${t.role||'Crew'}`]))} ${select('Function','crewFunction',[['','All / project level'],...projectFunctions(projectOf(projectId)||{}).map(f=>[f.id,f.name])])} ${field('Responsibility','crewResp')} ${field('Rate','crewRate','number','0')}</div>`,`<button class="btn primary" data-action="save-crew" data-project="${projectId}">Assign</button>`)}
function newProductionJobModal(type,projectId=''){const stages=type==='photo'?PHOTO_STAGES:VIDEO_STAGES;modal(`New ${type} production job`,`<div class="form-grid">${projectId?`<input id="jobProject" type="hidden" value="${projectId}">`:select('Event ID','jobProject',A.state.projects.map(p=>[p.id,`${p.event_code||''} · ${p.name}`]))} ${select('Function','jobFunction',[['','All / project level'],...A.state.functions.map(f=>[f.id,f.name])])} ${field('Job title','jobTitle','text',type==='photo'?'Photo edit':'Video edit')} ${select('Stage','jobStage',stages,stages[0])} ${field('Due date','jobDue','date')} ${select('Assign to','jobAssignee',[['','Unassigned'],...A.state.team.map(t=>[t.id,`${t.name} · ${t.role||'Crew'}`])])} ${textarea('Notes','jobNotes')}</div>`,`<button class="btn primary" data-action="save-job" data-type="${type}">Create job</button>`)}
function newFileModal(projectId){modal('Attach file / link',`<div class="form-grid">${projectId?`<input id="fileProject" type="hidden" value="${projectId}">`:select('Event ID','fileProject',A.state.projects.map(p=>[p.id,`${p.event_code||''} · ${p.name}`]))} ${field('Name','fileName')} ${select('Kind','fileKind',['Google Drive','Gallery','YouTube','Reference','Contract','Other'])} ${field('URL','fileUrl','url')} ${textarea('Notes','fileNotes')}</div>`,`<button class="btn primary" data-action="save-file">Attach</button>`)}
function newDeliverableModal(){modal('Add deliverable',`<div class="form-grid">${select('Event ID','dProject',A.state.projects.map(p=>[p.id,`${p.event_code||''} · ${p.name}`]))} ${field('Deliverable','dName','text','Pendrive')} ${field('Due date','dDue','date')} ${select('Status','dStatus',['pending','in_progress','delivered'],'pending')}</div>`,`<button class="btn primary" data-action="save-deliverable">Add</button>`)}
function newQuoteItemModal(qid,pid){modal('Add quotation item',`<div class="form-grid">${select('Function','qiFunction',[['','Project level'],...projectFunctions(projectOf(pid)||{}).map(f=>[f.id,f.name])])} ${field('Description','qiDesc')} ${field('Quantity','qiQty','number','1')} ${field('Customer price','qiPrice','number','0')} ${field('Internal cost','qiCost','number','0')}</div>`,`<button class="btn primary" data-action="save-quote-item" data-quote="${qid}" data-project="${pid}">Add</button>`)}
function serviceAmountModal(projectId,selected){const rows=selected.map((s,i)=>`<div class="amount-row"><div><b>${esc(s.name)}</b><small>${esc(s.brand||'')}</small></div><input id="svcPrice_${i}" type="number" placeholder="Customer price" value="${Number(s.customer_price||0)}"><input id="svcCost_${i}" type="number" placeholder="Internal cost" value="${Number(s.internal_cost||0)}"></div>`).join('');ui.serviceDraft=selected.slice();modal('Set service amounts',`<div class="rule-note">Enter the amount you will charge the client and your internal cost. These values roll into the Event ID's quotation and profit.</div><div id="svcAmountRows">${rows}</div><input type="hidden" id="svcProject" value="${projectId}">`,`<button class="btn primary" data-action="commit-services">Save amounts</button>`)}
function quickActionModal(){modal('Quick action',`<div class="quick-grid">${[['new-inquiry','New enquiry','Start sales pipeline'],['new-project','New event','Create Event ID'],['new-payment','Record payment','Customer or vendor'],['new-reminder','Reminder','Follow-up / deadline'],['new-team','Add freelancer','Crew directory'],['global-new-job','Production job','Photo or video tracker']].map(x=>`<button class="quick-action" data-action="${x[0]}"><b>${x[1]}</b><span>${x[2]}</span>→</button>`).join('')}</div>`)}
function authModal(){modal('Rachna OS account',A.state.user?`<p>Signed in as <b>${esc(A.state.user.email||'')}</b>.</p>`:`<div class="form-grid">${field('Email','loginEmail','email')} ${field('Password','loginPassword','password')}</div><div class="auth-note">Your workspace is connected to Supabase.</div>`,A.state.user?`<button class="btn primary" data-action="signout">Sign out</button>`:`<button class="btn primary" data-action="login">Sign in</button><button class="btn" data-action="signup">Create account</button>`)}
async function handleAction(action,el){try{switch(action){case'close':closeModal();break;case'new-inquiry':newInquiryModal();break;case'new-project':newProjectModal();break;case'new-client':newClientModal();break;case'new-team':newTeamModal();break;case'new-payment':newPaymentModal(el.dataset.project||'');break;case'record-payment':newPaymentModal('');break;case'new-reminder':newReminderModal(el.dataset.project||'');break;case'quick-action':quickActionModal();break;case'save-inquiry':await A.createInquiry({customer_name:$('#inqCustomer').value,phone:$('#inqPhone').value,event_name:$('#inqEvent').value,source:$('#inqSource').value,event_date_bs:$('#inqDate').value,venue:$('#inqVenue').value,guest_count:$('#inqGuests').value,budget:$('#inqBudget').value,notes:$('#inqNotes').value});closeModal();toast('Enquiry created');ui.page='home';render();break;case'save-project':{let c=null;if($('#pCustomer').value.trim())c=await A.createCustomer({name:$('#pCustomer').value,phone:$('#pPhone').value});const p=await A.insertProject({customer_id:c?.id||null,name:$('#pName').value,date_range_bs:$('#pDate').value,function_name:$('#pFunction').value,event_date_bs:$('#pDate').value.split(' ')[0],venue:$('#pVenue').value,guest_count:$('#pGuests').value,brand:$('#pBrand').value});closeModal();toast(`Event created · ${p.event_code||'Event ID assigned'}`);ui.project=p.id;render();break;}case'save-client':await A.createCustomer({name:$('#cName').value,phone:$('#cPhone').value,whatsapp:$('#cWhatsapp').value,email:$('#cEmail').value,notes:$('#cNotes').value});closeModal();toast('Client created');render();break;case'save-team':await A.addTeam({name:$('#tName').value,role:$('#tRole').value,phone:$('#tPhone').value,email:$('#tEmail').value});closeModal();toast('Freelancer added');render();break;case'convert-inquiry':{const p=await A.convertInquiry(el.dataset.id);ui.project=p.id;render();toast('Converted to Event ID');break;}case'open-project':ui.project=el.dataset.id;ui.tab='overview';render();break;case'back-events':ui.project=null;ui.page='events';render();break;case'new-function':newFunctionModal(el.dataset.project);break;case'save-function':await A.addFunction(el.dataset.project,{name:$('#fnName').value,event_date:$('#fnAD').value||null,start_time:$('#fnTime').value||null,venue:$('#fnVenue').value||null,guest_count:$('#fnGuests').value||null,event_date_bs:$('#fnBS').value||null,notes:$('#fnNotes').value||null});closeModal();toast('Function added');render();break;case'save-services':{const p=el.dataset.project,selected=[];$$('[data-svc]:checked').forEach(i=>selected.push({service_id:i.dataset.serviceId,name:i.dataset.name,brand:i.dataset.brand,customer_price:0,internal_cost:0,quantity:1}));const core=$('#aavartanCore');if(core?.checked){const pkg=$('input[name="aavPkg"]:checked')?.value||'Essential Package';selected.push({service_id:core.dataset.serviceId,name:`Aavartan Photo + Video — ${pkg}`,brand:'Aavartan',customer_price:0,internal_cost:0,quantity:1});$$('[data-addon]:checked').forEach(i=>selected.push({name:i.dataset.name,brand:'Aavartan',customer_price:0,internal_cost:0,quantity:1}));}closeModal();serviceAmountModal(p,selected);break;}case'commit-services':{const p=$('#svcProject').value,selected=(ui.serviceDraft||[]).map(s=>({...s}));selected.forEach((s,i)=>{s.customer_price=Number($(`#svcPrice_${i}`)?.value||0);s.internal_cost=Number($(`#svcCost_${i}`)?.value||0)});await A.saveProjectServiceScope(p,selected);closeModal();toast('Service scope saved');render();break;}case'new-vendor-job':newVendorJobModal(el.dataset.project);break;case'save-vendor-job':{const p=el.dataset.project,cost=Number($('#vjCost').value||0),client=Number($('#vjClient').value||0);await A.addVendorBooking({project_id:p,function_id:$('#vjFunction').value||null,vendor_id:$('#vjVendor').value,category:$('#vjCategory').value,requirement:$('#vjRequirement').value,quantity:Number($('#vjQuantity').value||1),client_price:client,quoted_cost:cost,payable:Math.max(0,cost),status:$('#vjStatus').value,notes:$('#vjNotes').value});closeModal();toast('Vendor job added');render();break;}case'assign-crew':assignCrewModal(el.dataset.project);break;case'save-crew':await A.assignTeam({project_id:el.dataset.project,team_member_id:$('#crewPerson').value,function_id:$('#crewFunction').value||null,responsibility:$('#crewResp').value,rate:Number($('#crewRate').value||0)});closeModal();toast('Crew assigned');render();break;case'save-payment':{const type=$('#payType').value,project=$('#payProject').value||null,amount=Number($('#payAmount').value||0);if(type==='advance'){if(!project)throw new Error('Choose an Event ID for an advance');const r=await A.recordAdvance(project,amount,$('#payMethod').value,$('#payRef').value);toast(r.booked?'30% advance reached · booking confirmed':'Advance recorded · booking still pending')}else if(type==='vendor')await A.recordPayment({project_id:project,direction:'out',party_type:'vendor',amount,payment_date:$('#payDate').value,method:$('#payMethod').value,reference:$('#payRef').value,notes:$('#payNotes').value});else if(type==='expense')await A.recordExpense({project_id:project,amount,expense_date:$('#payDate').value,method:$('#payMethod').value,category:'Other',description:$('#payNotes').value||'Expense',notes:$('#payRef').value});else await A.recordPayment({project_id:project,direction:'in',party_type:'customer',amount,payment_date:$('#payDate').value,method:$('#payMethod').value,reference:$('#payRef').value,notes:$('#payNotes').value});closeModal();render();break;}case'new-quote':{const p=el.dataset.project,q=await A.createQuotation(p),sv=projectServices(projectOf(p)||{});for(const s of sv)await A.addQuoteItem(q.id,{function_id:s.function_id||null,service_id:s.service_id||null,description:s.name,quantity:s.quantity||1,customer_price:s.customer_price||0,internal_cost:s.internal_cost||0});ui.tab='quotation';closeModal();toast('Quotation created');render();break;}case'quote-status':await A.updateQuotation(el.dataset.id,{status:el.dataset.status},el.dataset.project);toast(`Quotation marked ${el.dataset.status}`);render();break;case'new-quote-item':newQuoteItemModal(el.dataset.quote,el.dataset.project);break;case'save-quote-item':await A.addQuoteItem(el.dataset.quote,{function_id:$('#qiFunction').value||null,description:$('#qiDesc').value,quantity:Number($('#qiQty').value||1),customer_price:Number($('#qiPrice').value||0),internal_cost:Number($('#qiCost').value||0)});closeModal();toast('Quotation item added');render();break;case'global-new-job':newProductionJobModal(el.dataset.type);break;case'new-job':newProductionJobModal(el.dataset.type,el.dataset.project);break;case'save-job':await A.addProductionJob({project_id:$('#jobProject').value,function_id:$('#jobFunction').value||null,brand:'Aavartan',job_type:el.dataset.type,tracker_type:el.dataset.type,title:$('#jobTitle').value,stage:$('#jobStage').value,due_date:$('#jobDue').value||null,assigned_to:$('#jobAssignee').value||null,notes:$('#jobNotes').value});closeModal();toast('Production job created');render();break;case'done-reminder':await A.updateReminder(el.dataset.id,{status:'done'});toast('Reminder completed');render();break;case'new-file':newFileModal(el.dataset.project);break;case'save-file':await A.addEventFile({project_id:$('#fileProject').value,name:$('#fileName').value,kind:$('#fileKind').value,url:$('#fileUrl').value,notes:$('#fileNotes').value});closeModal();toast('File link attached');render();break;case'delete-file':await A.removeEventFile(el.dataset.id);toast('File removed');render();break;case'new-deliverable':newDeliverableModal();break;case'save-deliverable':await A.addDeliverable({project_id:$('#dProject').value,deliverable:$('#dName').value,due_date:$('#dDue').value,status:$('#dStatus').value});closeModal();toast('Deliverable added');render();break;case'complete-deliverable':await A.updateDeliverable(el.dataset.id,{status:'delivered',delivered_at:new Date().toISOString()},el.dataset.project);toast('Marked delivered');render();break;case'save-reminder':await A.addReminder({project_id:$('#rProject').value||null,title:$('#rTitle').value,due_at:$('#rDue').value||null,priority:$('#rPriority').value,reminder_type:$('#rType').value,notes:$('#rNotes').value});closeModal();toast('Reminder created');render();break;case'login':await A.signIn($('#loginEmail').value,$('#loginPassword').value);closeModal();toast('Signed in');render();break;case'signup':{const email=$('#loginEmail').value,password=$('#loginPassword').value;if(!email||!password)throw new Error('Enter email and password first');const r=await A.signUp(email,password,email.split('@')[0],'Rachna Workspace');closeModal();toast(r.needsConfirmation?'Check your email to confirm account':'Workspace created');render();break;}case'signout':await A.signOut();break;case'inquiry-stage':ui.inquiryStage=el.dataset.stage;render();break;}}catch(e){toast(e.message||'Something went wrong',true)}}
document.addEventListener('click',e=>{const t=e.target.closest('[data-action]');if(t){e.preventDefault();handleAction(t.dataset.action,t);return}const r=e.target.closest('[data-route]');if(r){e.preventDefault();ui.project=null;ui.page=r.dataset.route;ui.query='';render();return}const pt=e.target.closest('[data-project-tab]');if(pt){ui.tab=pt.dataset.projectTab;render();return}});
document.addEventListener('change',async e=>{const stage=e.target.closest('[data-job-stage]');if(stage){try{await A.updateProductionJob(stage.dataset.jobStage,{stage:e.target.value,status:e.target.value==='Delivered'?'completed':'in_progress'});toast('Production stage updated');render()}catch(err){toast(err.message,true)}}});
document.addEventListener('input',e=>{if(['eventSearch','projectSearch','clientSearch','fileSearch'].includes(e.target.id)){ui.query=e.target.value;render()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
$('#refresh').onclick=async()=>{try{await A.refresh();render();toast('Workspace refreshed')}catch(e){toast(e.message,true)}};$('#authBtn').onclick=()=>authModal();
(async()=>{try{await A.init();render();if(!A.state.user)authModal()}catch(e){A.state.error=e;render();modal('Connection error',`<p class="error-copy">${esc(e.message||'Unable to connect to workspace')}</p>`)}})();
})();